head.b:skin:
:root{--ink:#14263d;--muted:#60738a;--paper:#f4f7fb;--surface:#fff;--line:#e3eaf2;--brand:#176b87;--brand2:#2556a6;--accent:#f59e0b;--shadow:0 16px 45px rgba(24,49,79,.09);--radius:20px}
*{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:90px}
body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.7 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
a{color:var(--brand2);text-decoration:none}a:hover{text-decoration:underline}
img{max-width:100%;height:auto}
.skip{position:absolute;left:-9999px}.skip:focus{left:12px;top:12px;z-index:1000;background:#fff;padding:10px}
.topline{height:5px;background:linear-gradient(90deg,var(--brand),var(--brand2),var(--accent))}
.sitehead{position:sticky;top:0;z-index:50;background:rgba(255,255,255,.9);backdrop-filter:blur(16px);border-bottom:1px solid rgba(220,230,240,.85)}
.headin{max-width:1160px;margin:auto;padding:12px 22px;display:flex;align-items:center;justify-content:space-between;gap:18px}
.brand{min-width:0;color:var(--ink);font-weight:850;font-size:1.22rem;letter-spacing:-.03em;display:flex;align-items:center;gap:10px}
.brandmark{width:38px;height:38px;border-radius:13px;background:linear-gradient(135deg,var(--brand),var(--brand2));display:grid;place-items:center;color:white;font-weight:900;box-shadow:0 8px 18px rgba(23,107,135,.22)}
.headlinks{display:flex;gap:16px;align-items:center;font-size:.9rem;font-weight:650}
.headlinks a{color:#344b63}.headlinks a:hover{color:var(--brand)}
.wrap{max-width:1160px;margin:30px auto 110px;padding:0 22px;display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:26px}
.hero{background:linear-gradient(125deg,#123b5a,#176b87 58%,#2556a6);color:#fff;border-radius:26px;padding:30px 32px;margin-bottom:24px;box-shadow:var(--shadow);position:relative;overflow:hidden}
.hero:after{content:"";position:absolute;width:240px;height:240px;border:1px solid rgba(255,255,255,.18);border-radius:50%;right:-75px;top:-95px;box-shadow:0 0 0 28px rgba(255,255,255,.05),0 0 0 58px rgba(255,255,255,.035)}
.eyebrow{font-size:.75rem;text-transform:uppercase;letter-spacing:.14em;font-weight:800;opacity:.82}
.hero h1{font-size:clamp(1.65rem,4vw,2.55rem);line-height:1.15;letter-spacing:-.04em;margin:8px 0 10px;max-width:720px}
.hero p{margin:0;max-width:700px;color:rgba(255,255,255,.86)}
.heroactions{display:flex;flex-wrap:wrap;gap:10px;margin-top:20px}
.pill{display:inline-flex;align-items:center;justify-content:center;padding:9px 15px;border-radius:999px;font-weight:750;font-size:.88rem;background:#fff;color:#143d5b}
.pill.ghost{background:rgba(255,255,255,.13);color:#fff;border:1px solid rgba(255,255,255,.35)}
.panel,.widget{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow)}
.mainpanel{padding:22px;min-width:0}
.sectiontitle{font-size:1.18rem;line-height:1.3;margin:0 0 16px;font-weight:850;letter-spacing:-.02em}
.blog-posts{display:grid;gap:18px}
.post-outer{padding:0 0 18px;border-bottom:1px solid var(--line)}
.post-outer:last-child{border-bottom:0}
h2.post-title,h3.post-title{font-size:1.28rem;line-height:1.35;margin:0 0 8px;letter-spacing:-.02em}
.post-title a{color:var(--ink)}
.post-header,.post-footer,.post-timestamp{color:var(--muted);font-size:.85rem}
.post-body{overflow-wrap:anywhere;color:#344b63}
.post-body h2,.post-body h3{color:var(--ink);line-height:1.3}
.post-body img{border-radius:14px}
.post-body blockquote{margin:18px 0;padding:12px 18px;border-left:4px solid var(--brand);background:#f0f6fa;border-radius:0 12px 12px 0}
.post-body table{display:block;max-width:100%;overflow-x:auto;border-collapse:collapse}
.post-body th,.post-body td{border:1px solid var(--line);padding:9px;text-align:left}
.sidebar{display:grid;align-content:start;gap:18px}
.widget{padding:18px;min-width:0}.widget h2,.widget h3{font-size:1rem;margin:0 0 12px}
.widget ul{margin:0;padding-left:19px}.widget li{margin:6px 0}
.network{display:grid;gap:9px}
.network a{padding:10px 12px;border-radius:12px;background:#f3f7fb;color:#23425f;font-weight:700}
.network a:hover{background:#e8f2f7;text-decoration:none}
.searchbox{display:flex;gap:8px}.searchbox input{width:100%;min-width:0;border:1px solid var(--line);border-radius:12px;padding:11px;font:inherit}.searchbox button{border:0;border-radius:12px;padding:0 14px;background:var(--brand);color:#fff;font-weight:800}
.sitefoot{max-width:1160px;margin:0 auto;padding:22px;color:var(--muted);font-size:.88rem;text-align:center}
.bottomnav{display:none}
.toTop{position:fixed;right:20px;bottom:24px;z-index:60;border:0;border-radius:50%;width:46px;height:46px;background:var(--brand2);color:#fff;font-size:20px;box-shadow:var(--shadow);cursor:pointer}
body.dark{--ink:#e8f0f8;--muted:#a8b8c8;--paper:#0b1522;--surface:#111f30;--line:#26384b;--brand:#4bb3c7;--brand2:#6f9ff0;--shadow:0 16px 45px rgba(0,0,0,.22)}
body.dark .sitehead{background:rgba(13,27,42,.9);border-color:var(--line)}
body.dark .headlinks a,body.dark .post-title a{color:var(--ink)}
body.dark .post-body{color:#c6d4e2}
body.dark .network a,body.dark .post-body blockquote{background:#192c40;color:#d8e7f4}
body.dark .hero{background:linear-gradient(125deg,#10283d,#15546a 58%,#263f79)}
@media(max-width:850px){.wrap{grid-template-columns:1fr;margin-top:18px}.sidebar{grid-template-columns:repeat(2,minmax(0,1fr))}.headlinks{display:none}}
@media(max-width:600px){body{font-size:15px}.headin{padding:9px 15px}.wrap{padding:0 13px;margin:14px auto 100px;gap:15px}.hero{padding:23px 20px;border-radius:20px}.mainpanel{padding:16px}.sidebar{grid-template-columns:1fr}.bottomnav{position:fixed;z-index:100;left:10px;right:10px;bottom:calc(9px + env(safe-area-inset-bottom));display:grid;grid-template-columns:repeat(4,1fr);gap:4px;padding:7px;background:rgba(255,255,255,.92);backdrop-filter:blur(18px);border:1px solid rgba(205,219,232,.9);border-radius:19px;box-shadow:0 12px 35px rgba(15,39,65,.18)}.bottomnav a,.bottomnav button{border:0;background:transparent;color:#34516d;display:grid;justify-items:center;gap:1px;font:700 10px system-ui;padding:5px 2px}.bottomnav span{font-size:19px;line-height:1.2}body.dark .bottomnav{background:rgba(17,31,48,.94);border-color:var(--line)}body.dark .bottomnav a,body.dark .bottomnav button{color:#d9e8f5}.toTop{display:none}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{animation-duration:.01ms!important;transition-duration:.01ms!important}}

body.script:
//
(function(){
  var body=document.body, toggle=document.getElementById('themeToggle');
  try{if(localStorage.getItem('na-theme')==='dark'){body.classList.add('dark');}}catch(e){}
  if(toggle){toggle.addEventListener('click',function(){body.classList.toggle('dark');try{localStorage.setItem('na-theme',body.classList.contains('dark')?'dark':'light');}catch(e){}});}
  function top(){window.scrollTo({top:0,behavior:'smooth'});}
  ['topButton','floatingTop'].forEach(function(id){var el=document.getElementById(id);if(el)el.addEventListener('click',top);});
  var network=document.getElementById('networkButton');
  if(network)network.addEventListener('click',function(){var target=document.querySelector('.sidebar .network');if(target){target.scrollIntoView({behavior:'smooth',block:'center'});target.style.outline='3px solid rgba(23,107,135,.25)';setTimeout(function(){target.style.outline='';},1400);}});
})();
//
